import { expectAutomaticPremiumShine } from "../helpers/premium-shine";
import { randomUUID } from "node:crypto";
import { Pool } from "pg";
import AxeBuilder from "@axe-core/playwright";
import type { Locator } from "@playwright/test";
import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
test.afterAll(() => pool.end());
test.use({ reducedMotion: "reduce" });

for (const theme of ["light", "dark"]) {
  test(`Premium feature clicks open upgrade without changing data (${theme})`, async ({
    page,
    themeUser,
  }, info) => {
    test.setTimeout(120000);
    await setThemeQuotaGating(true);
    await setThemePlan(themeUser, "FREE");
    const template = randomUUID(),
      retained = randomUUID(),
      contact = randomUUID(),
      sentContact = randomUUID(),
      campaign = randomUUID(),
      send = randomUUID();
    await pool.query(
      `UPDATE "User" SET "preferredRoles"=ARRAY['Engineer','Designer'] WHERE id=$1`,
      [themeUser],
    );
    await pool.query(
      `INSERT INTO "Template" (id,"userId",name,subject,body,"createdAt") VALUES ($1,$3,'Active template','Hello {{name}}','Original body',NOW()-interval '1 day'),($2,$3,'Retained template','Retained subject','Retained body',NOW())`,
      [template, retained, themeUser],
    );
    await pool.query(
      `INSERT INTO "Contact" (id,"userId",name,email,"jobRole") VALUES ($1,$3,'New recipient','[REDACTED_EMAIL]','Engineer'),($2,$3,'Sent recipient','[REDACTED_EMAIL]','Engineer')`,
      [contact, sentContact, themeUser],
    );
    await pool.query(
      `INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,'COMPLETED')`,
      [campaign, themeUser, template],
    );
    await pool.query(
      `INSERT INTO "Send" (id,"campaignId","contactId","recipientName","recipientEmail",status,"deliveryState","sentAt") VALUES ($1,$2,$3,'Sent recipient','[REDACTED_EMAIL]','SENT','DONE',NOW())`,
      [send, campaign, sentContact],
    );
    await page.addInitScript(
      (value) => localStorage.setItem("mailloop-theme", value),
      theme,
    );
    page.on("dialog", (dialog) => dialog.accept());
    const actions: string[] = [];
    // Read-only sending-status polling has no arguments; restricted actions do.
    page.on("request", (request) => {
      if (
        (request.headers()["next-action"] && request.postData() !== "[]") ||
        new URL(request.url()).pathname === "/api/billing/checkout"
      )
        actions.push(request.url());
    });
    const dialog = page.getByRole("dialog", {
      name: "Upgrade to Premium",
      exact: true,
    });
    async function checkPopup(feature: string, focus?: Locator) {
      const contexts: Record<string, [string, string]> = {
        "Follow-up reminders": [
          "reminders",
          "Follow-up reminders are a Premium feature",
        ],
        "More role shortcuts": [
          "role-shortcuts",
          "More than two role shortcuts is a Premium feature",
        ],
        "Premium themes": [
          "themes",
          "Chalk and Obsidian themes are Premium features",
        ],
        "CSV import": ["csv", "CSV import is a Premium feature"],
        "Using retained templates": [
          "templates",
          "More than one saved template is a Premium feature",
        ],
        "Editing retained templates": [
          "templates",
          "More than one saved template is a Premium feature",
        ],
        "Recipient role editing": [
          "roles",
          "Role editing is a Premium feature",
        ],
        "Custom preview highlight colors": [
          "highlights",
          "Custom preview highlight colors are a Premium feature",
        ],
        "Reply tracking": ["replied", "“Mark replied” is a Premium feature"],
        "Adding contacts from History": [
          "shortlist",
          "Add to shortlist from History is a Premium feature",
        ],
      };
      const [key, text] = contexts[feature];
      await expect(dialog).toBeVisible();
      await expect(dialog).toContainText(text);
      await expect(
        dialog.getByRole("button", { name: /^Upgrade for / }),
      ).toBeEnabled();
      expect(
        await dialog.evaluate((element) => {
          const box = element.getBoundingClientRect();
          return (
            box.left >= 0 &&
            box.right <= innerWidth &&
            box.top >= 0 &&
            box.bottom <= innerHeight
          );
        }),
      ).toBe(true);
      await expect(dialog.locator('[data-highlighted="true"]')).toHaveCount(1);
      await expect(dialog.locator('[data-highlighted="true"]')).toHaveAttribute(
        "data-upgrade-feature",
        new RegExp(`(^| )${key}( |$)`),
      );
      await expect(
        dialog.locator('[aria-live="polite"] > span').last(),
      ).toHaveText(text);
      await expect(
        dialog.locator('article[aria-label="Premium plan"] li'),
      ).toHaveCount(10);
      await expect(
        dialog.locator('article[aria-label="Free plan"] li'),
      ).toHaveCount(5);
      await expect(dialog.locator("details")).toHaveCount(0);
      await page.keyboard.press("Escape");
      await expect(dialog).toHaveCount(0);
      if (focus) await expect(focus).toBeFocused();
    }

    await page.goto("/settings");
    const delay = page.getByRole("button", {
      name: "Follow-up reminder delay · Premium required",
    });
    await expect(delay).toHaveCSS("cursor", "pointer");
    await delay.focus();
    await page.keyboard.press("Enter");
    await checkPopup("Follow-up reminders", delay);
    await page
      .getByRole("button", { name: "Save reminders", exact: true })
      .click();
    await checkPopup("Follow-up reminders");
    const roleInput = page.getByLabel("Custom role", { exact: true });
    await roleInput.fill("Draft role");
    await page.getByRole("button", { name: "Add role", exact: true }).click();
    await checkPopup("More role shortcuts");
    await expect(roleInput).toHaveValue("Draft role");
    await expect(page.locator("#outreach")).toContainText(
      "2 of 2 roles selected",
    );
    await roleInput.fill("");

    const appearance = page.getByRole("button", {
      name: "Choose appearance",
      exact: true,
    });
    await appearance.click();
    const chalk = page.getByRole("menuitemradio", { name: /Chalk/ });
    await expect(chalk).toHaveCSS("cursor", "pointer");
    await chalk.click();
    await expect(dialog).toBeVisible();
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    await page.screenshot({ path: info.outputPath(`upgrade-${theme}.png`) });
    await checkPopup("Premium themes", appearance);
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      "purple",
    );

    await page.goto("/contacts");
    const csv = page.getByRole("button", {
      name: "Choose a CSV file · Premium required",
    });
    let filePickers = 0;
    page.on("filechooser", () => filePickers++);
    await csv.click();
    await checkPopup("CSV import", csv);
    expect(filePickers).toBe(0);
    await page.goto("/compose");
    const templatePicker = page.getByLabel("Choose a template", {
      exact: true,
    });
    await templatePicker.selectOption(template);
    await templatePicker.selectOption(retained);
    await checkPopup("Using retained templates", templatePicker);
    await expect(templatePicker).toHaveValue(template);
    await page.getByRole("checkbox", { name: /New recipient/ }).check();
    const role = page.getByRole("button", {
      name: "Recipient role · Premium required",
    });
    await role.click();
    await checkPopup("Recipient role editing", role);
    const highlight = page.getByRole("button", {
      name: "Highlight color",
      exact: true,
    });
    await highlight.click();
    await page
      .getByRole("menuitemradio", {
        name: "Blue — Premium required",
        exact: true,
      })
      .click();
    await checkPopup("Custom preview highlight colors", highlight);
    await expect(page.locator(".mail-preview")).toHaveAttribute(
      "data-preview-highlight",
      "cyan",
    );
    await expect(
      page.getByRole("checkbox", { name: /New recipient/ }),
    ).toBeChecked();

    await page.goto("/history");
    await page
      .getByRole("button", { name: "Mark replied", exact: true })
      .click();
    await checkPopup("Reply tracking");
    await page
      .getByRole("button", { name: "Add to shortlist", exact: true })
      .click();
    await checkPopup("Adding contacts from History");
    // Manual repeat sending remains available on Free.
    await pool.query(
      `UPDATE "Contact" SET "followUpRequestedAt"=NOW() WHERE id=$1 AND "userId"=$2`,
      [sentContact, themeUser],
    );
    await page.goto("/compose");
    const repeatSelection = page.getByRole("checkbox", {
      name: /Sent recipient/,
    });
    await repeatSelection.click();
    await expect(repeatSelection).toBeChecked();
    await expect(dialog).toHaveCount(0);

    // An editor opened on Premium retains its unsaved draft after downgrade.
    await setThemePlan(themeUser, "PAID");
    await page.goto(`/templates?edit=${retained}`);
    const subject = page.getByLabel("Subject", { exact: true });
    await subject.fill("Unsaved draft");
    await setThemePlan(themeUser, "FREE");
    await expect(async () => {
      await page.evaluate(() =>
        window.dispatchEvent(new Event("mailloop:access-refresh")),
      );
      await expect(subject).toHaveAttribute("readonly", "", { timeout: 1000 });
    }).toPass({ timeout: 15000 });
    const save = page.getByRole("button", {
      name: "Save template",
      exact: true,
    });
    await save.click();
    await checkPopup("Editing retained templates", save);
    await expect(subject).toHaveValue("Unsaved draft");
    expect(actions).toEqual([]);
    expect(
      (
        await pool.query(
          `SELECT subject FROM "Template" WHERE id=$1 AND "userId"=$2`,
          [retained, themeUser],
        )
      ).rows[0].subject,
    ).toBe("Retained subject");
    expect(
      (
        await pool.query(
          `SELECT status FROM "Send" WHERE id=$1 AND "campaignId" IN (SELECT id FROM "Campaign" WHERE "userId"=$2)`,
          [send, themeUser],
        )
      ).rows[0].status,
    ).toBe("SENT");
  });
}

test("account suspension keeps feature controls unavailable", async ({
  page,
  themeUser,
}) => {
  await setThemeQuotaGating(true);
  await setThemePlan(themeUser, "FREE");
  await pool.query(
    `UPDATE "User" SET "isSuspended"=true,"suspendedAt"=NOW(),"suspensionReason"='Browser fixture' WHERE id=$1`,
    [themeUser],
  );
  await page.goto("/settings");
  await expect(
    page.getByRole("button", {
      name: "Follow-up reminder delay · Premium required",
    }),
  ).toBeDisabled();
  await expect(
    page.getByRole("button", { name: "Save reminders", exact: true }),
  ).toBeDisabled();
  await page.goto("/contacts");
  await expect(
    page.getByRole("button", { name: "Choose a CSV file · Premium required" }),
  ).toBeDisabled();
  await expect(
    page.getByRole("dialog", { name: "Upgrade to Premium", exact: true }),
  ).toHaveCount(0);
});

test("open upgrade follows the existing appearance switcher live", async ({
  page,
  themeUser,
}, info) => {
  test.skip(info.project.name !== "desktop", "Own theme matrix");
  await setThemeQuotaGating(true);
  await setThemePlan(themeUser, "FREE");
  await page.goto("/settings");
  await page
    .getByRole("button", {
      name: "Follow-up reminder delay · Premium required",
    })
    .click();
  const dialog = page.getByRole("dialog", {
    name: "Upgrade to Premium",
    exact: true,
  });
  await expect(dialog).toBeVisible();
  await dialog.evaluate((el) => {
    el.dataset.liveCheck = "retained";
  });
  // Grant theme access after opening; retain the same mounted upgrade dialog.
  await setThemePlan(themeUser, "PAID");
  await page.evaluate(() =>
    window.dispatchEvent(new Event("mailloop:access-refresh")),
  );
  const switcher = page.locator('button[aria-label="Choose appearance"]');
  for (const [name, appearance, mode, surface] of [
    ["Lavender", "purple", "light", "rgb(246, 241, 255)"],
    ["Nightbloom", "purple", "dark", "rgb(14, 10, 29)"],
    ["Chalk", "vercel", "light", "rgb(243, 243, 243)"],
    ["Obsidian", "vercel", "dark", "rgb(10, 10, 10)"],
  ]) {
    // A modal intentionally blocks physical background interaction. Invoke the
    // existing switcher's controls to exercise its actual event handlers.
    await switcher.evaluate((el: HTMLButtonElement) => el.click());
    const option = page.locator(".appearance-option").filter({ hasText: name });
    await expect(option.locator(".appearance-lock")).toHaveCount(0);
    await option.evaluate((el: HTMLButtonElement) => el.click());
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
    await expect(dialog).toHaveCSS("background-color", surface);
    await expect(dialog).toHaveAttribute("data-live-check", "retained");
    await expect(dialog.locator('[data-highlighted="true"]')).toHaveAttribute(
      "data-upgrade-feature",
      "reminders",
    );
    expect(
      await page.evaluate(() => localStorage.getItem("mailloop-theme")),
    ).toBe(mode);
    expect(
      (await new AxeBuilder({ page }).include('[role="dialog"]').analyze())
        .violations,
    ).toEqual([]);
    await dialog.screenshot({ path: info.outputPath(`live-${name}.png`) });
  }
  await page.emulateMedia({ reducedMotion: "no-preference" });
  const card = dialog.getByRole("article", {
    name: "Premium plan",
    exact: true,
  });
  await dialog.locator("[data-upgrade-body]").evaluate((el) => {
    el.scrollTop = 0;
  });
  await card.hover({ position: { x: 50, y: 50 } });
  expect(
    await card.evaluate((el) => el.style.getPropertyValue("--spot-x")),
  ).not.toBe("");
  await expect(card.locator(".upgrade-spotlight")).toHaveCSS("opacity", "1");
  const pointerBefore = await card.evaluate((el) =>
    el.style.getPropertyValue("--spot-x"),
  );
  await page.emulateMedia({ reducedMotion: "reduce" });
  await card.dispatchEvent("pointermove", {
    pointerType: "mouse",
    clientX: 300,
    clientY: 300,
  });
  expect(
    await card.evaluate((el) => el.style.getPropertyValue("--spot-x")),
  ).toBe(pointerBefore);
  await expect(card.locator(".upgrade-spotlight")).toHaveCSS("opacity", "0");
  const upgrade = dialog.getByRole("button", { name: /^Upgrade for / });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.mouse.move(0, 0);
  await expectAutomaticPremiumShine(upgrade);
  await upgrade.evaluate((el) => el.setAttribute("aria-busy", "true"));
  expect(
    await upgrade.evaluate((el) => getComputedStyle(el, "::before").display),
  ).toBe("none");
  await upgrade.evaluate((el) => el.removeAttribute("aria-busy"));
  await page.emulateMedia({ reducedMotion: "reduce" });
  expect(
    await upgrade.evaluate((el) => getComputedStyle(el, "::before").display),
  ).toBe("none");
  await page.keyboard.press("Escape");
  await expect(dialog).toHaveCount(0);
});
